
import { Blob } from 'react-blob'
import ReactHtmlParser from 'react-html-parser'; 
import AboutUsItem from './aboutusitem'
import {TEXT_ABOUT_TITLE, TEXT_ABOUT_TEXT, IMG_DEVELOPMENT, IMG_DESIGN, IMG_CONTENT, 
    TEXT_ABOUT_DIGITAL, TEXT_ABOUT_DESIGN, TEXT_ABOUT_CONTENT,
    TEXT_ABOUT_LIST_DIGITAL, TEXT_ABOUT_LIST_DESIGN, TEXT_ABOUT_LIST_CONTENT} from '../configs/content'


class AboutUs extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
          loaded: false
        };
      }
    componentDidMount(){
      this.setState({loaded: true})
    }
    render() {
        const bob = this.state.loaded ? <Blob size="40vh" id="background_aboutus_blob"
        style={{
        position: 'absolute',
        zIndex: -1,
        opacity: 1,
        fontSize: '50vh',
    }} /> : ""
        return (
            <section id="section_aboutus" className="full_width">
                <div className="container_section">
                    <div className="text_block">
                        {bob}
                        <div className="text_title_big">
                            {TEXT_ABOUT_TITLE}
                        </div>
                        <div className="text_paragraph">
                            { ReactHtmlParser (TEXT_ABOUT_TEXT)}
                        </div>
                    </div>


                <div className="aboutus_container">
                    <div className="aboutus_container__inner">
                        <AboutUsItem imgURL={IMG_DEVELOPMENT} title={TEXT_ABOUT_DIGITAL} listContent={TEXT_ABOUT_LIST_DIGITAL}/>
                        <AboutUsItem imgURL={IMG_DESIGN} title={TEXT_ABOUT_DESIGN} listContent={TEXT_ABOUT_LIST_DESIGN}/>
                        <AboutUsItem imgURL={IMG_CONTENT} title={TEXT_ABOUT_CONTENT} listContent={TEXT_ABOUT_LIST_CONTENT}/>
                    </div>
                </div>


                </div>
            </section>
        )
    }
}

export default AboutUs


 