import PropTypes from 'prop-types';
import {data_projects} from "../configs/data";
import Collapse from 'react-bootstrap/Collapse';
import Helper from './Helper.js';
import Router from 'next/router';
import {project_properties}  from '../configs/props.js';
const ProjectProperties = project_properties;

  class AllProjects extends React.Component {
    _isMounted = false;

    constructor(props) {
        super(props);
        this.myRef = React.createRef();
        // This binding is necessary to make `this` work in the callback
        this.handleClick = this.handleClick.bind(this);
        const  crossoriginalStatus = this.props.crossoriginalStatus || false;
        this.state = {
            isCrossOpen: crossoriginalStatus,
            firstTime: true,
            width: 120,
        }
    }
    HandlePageChange() {
        Helper.enterTransition();
    }
    updateDimensions() {
        if (!this._isMounted) return;
        let sideReducer = 2;
        let numberItem = 5;
        const wrapper_content = this.myRef.current.clientWidth;
        let windowWidth = (wrapper_content) ? wrapper_content : window.innerWidth;
        if (windowWidth > 1600) windowWidth = 1600;
        if (!wrapper_content) {
            sideReducer = 122;
        }
        if(windowWidth < 720) {
            numberItem = 4;
        } 
        if(windowWidth < 600) {
            numberItem = 3;
        } 
        if(windowWidth < 480) {
            numberItem = 2;
        }

        // Because the images have padding: 4px
        sideReducer += (numberItem * 8);

        const width_aux = Math.round(((windowWidth-sideReducer)/numberItem));
        this.setState({ width: width_aux});
      }
    componentDidMount() {
        this._isMounted = true;
        this.updateDimensions();
        window.addEventListener("resize", this.updateDimensions.bind(this));
      }
    componentWillUnmount() {
        this._isMounted = false;
        window.removeEventListener("resize", this.updateDimensions.bind(this));
      }
    handleClick() {      
        const {isCrossOpen} = this.state;
        this.setState({
            isCrossOpen: !isCrossOpen,
            firstTime: false,
        });
        this.updateDimensions();
    }

    render() {
        const {isCrossOpen, firstTime} = this.state;
        const classNames = 'cross cross--spin js-cross cross-layer-black'  +(isCrossOpen ? ' is-active' : '');
        const classVisible = 'hover15 all_projects_bottom';  
        return (
            <section id="all_projects" className="full_width">
                <div className="section_container">
                    <div className="all_projects_top" ref={this.myRef}>
                        <div onClick={this.handleClick} className="allprojects_title_block">
                            <div className="allprojects_title_text">
                                Show All the projects
                            </div >
                            <div className={classNames} 
                                aria-label="Menu" aria-controls="navigation">
                                <span className="cross-box">
                                    <span className="cross-inner"></span>
                                </span>
                            </div>
                        </div>
                    </div>
           
                    <Collapse in={isCrossOpen}>   
                        <div className={classVisible} >
                            {
                            data_projects.map((item,index) => {

                            return (
                            <a onClick={() => { this.HandlePageChange(), setTimeout(() => {Router.push(`/project?slug=` + item.id,`/projects/` + item.id)}, ProjectProperties.time_transition) }  } key={`allprojects_a_${index}`} >
                                <figure>
                                <img
                                    key={`allprojects_img_${index}`} 
                                    className="projects_img_link"
                                    src={item.img_logo}
                                    alt={item.title}
                                    style={{width: this.state.width}} 
                                ></img>
                                </figure>
                            </a>)
                            })
                            } 
                            <div className="clean"></div>
                        </div>
                    </Collapse>

                </div>
            </section>
        );
    }
  }

  AllProjects.propTypes = {
    isOpen: PropTypes.bool,
  };


  export default AllProjects;