class Helper  {
	static enterTransition () {
        document.body.classList.remove("hide-scroll");
        document.body.classList.add("hide-scroll");

        let cortinilla = document.getElementById("cortinilla");
        cortinilla.classList.remove("transition-animate");
        cortinilla.classList.remove("transition-animate-reverse");
        cortinilla.classList.add("transition-animate");
    }
    
    static exitTransition () {
        if (document.body.classList.contains('hide-scroll')) {
            document.body.classList.remove("hide-scroll");
        }
        let cortinilla = document.getElementById("cortinilla");

        if (cortinilla.classList.contains('transition-animate')) {
            cortinilla.classList.remove("transition-animate");
            cortinilla.classList.remove("transition-animate-reverse");
            cortinilla.classList.add("transition-animate-reverse");  
        }
    }
}

export default Helper;