

export default ({imgURL, title, listContent}) => {
    const titAux = title.replace(/ +/g, "");
    return (
    <div className="aboutus_item">
        <div className="aboutus_item_wrapper">
            <div className="aboutus_item_img">
                <img src={imgURL} alt="" />
            </div>
            <div className="aboutus_item_title">{title}</div>
            <div className="aboutus_item_content">
                <ul className="aboutus_item_list">
                    {
                     listContent.map((item,index) =>{
                        return (
                            <li className="aboutus_item_list--element" key={titAux + "" + index}>{item}</li>
                        )
                     })
                    }
                </ul>
            </div>
        </div>
    </div>
    )
}

 