import Link from "next/link";
import ReactDOM from 'react-dom';
import Helper from './Helper.js';
import Router from 'next/router';
import {project_properties}  from '../configs/props.js';

const ProjectProperties = project_properties;

class ProjectFeatured extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            isHide: false,
            objMeasures: {}
        };
        this.HandlePageChange= this.HandlePageChange.bind(this);
    }
    hideBlock = () => {
        const { isHide, objMeasures } = this.state
        /*{
            bottom
            height
            left
            right
            top
            width
            x
            y
        }*/
        if(isHide) {
            // We only do the animation once
            return;
        };
        (window.scrollY  >  (objMeasures.y - 50 )) ?
        !isHide && this.setState({ isHide: true })
        :
        isHide && this.setState({ isHide: false });

     }
 

    componentDidMount() {
        const objMeasures = ReactDOM.findDOMNode(this).getBoundingClientRect();
        this.setState( {objMeasures: objMeasures});
        window.addEventListener('scroll', this.hideBlock);
    }
  
    componentWillUnmount() {
        window.removeEventListener('scroll', this.hideBlock);
    }
  
    handleScrollToElement(event) {
    }

    HandlePageChange() {
        Helper.enterTransition();
    }
    
    render() { 
        return (
            <div className={`project__general project__general_${this.props.index}`}  data-aos={ this.props.right ? `zoom-out-left` : `zoom-out-right` }>
                <div className={`project__details project_details_${this.props.index}`}>
                    <a onClick={() => { this.HandlePageChange(), setTimeout(() => {Router.push(`/project?slug=` + this.props.slug,`/projects/` + this.props.slug)}, ProjectProperties.time_transition) } }>
                        <img className={`cursor_pointer project__details-bg project__details-bg-animated project__details-bg_${this.props.index}`} src={this.props.background_img} />    
                    </a>
                </div>
                <a onClick={() => { this.HandlePageChange(), setTimeout(() => {Router.push(`/project?slug=` + this.props.slug,`/projects/` + this.props.slug)}, ProjectProperties.time_transition) } }>
                    <figure>
                        <img className={`cursor_pointer project__background block_shadow project__background_${this.props.index}`} src={this.props.project_img} />  
                    </figure>
                </a>
                <a onClick={() => { this.HandlePageChange(), setTimeout(() => {Router.push(`/project?slug=` + this.props.slug,`/projects/` + this.props.slug)}, ProjectProperties.time_transition) } }>
                    <img id={this.props.slug}  className={`cursor_pointer project__logo block_shadow project__logo_${this.props.index}`} src={this.props.logo} />
                </a>
                <a onClick={() => { this.HandlePageChange(), setTimeout(() => {Router.push(`/project?slug=` + this.props.slug,`/projects/` + this.props.slug)}, ProjectProperties.time_transition) } }>
                    <div className={`cursor_pointer  project_text project_text_${this.props.index}`}>
                        <div className={`project_text_row_up project_text_row_up_${this.props.index}`}>
                            <div className={`color_square color_square_dark_orange color_square_${this.props.index}`}></div>
                            <div className={`project_text_small project_text_small_${this.props.index}`}>
                                {this.props.company}
                            </div>
                        </div>
                        <div className={`project_text_row_down project_text_big project_text_row_down_${this.props.index}`}>
                            {this.props.project_title}
                        </div>
                    </div>
                </a>
            </div> 
        )
    }
}

export default ProjectFeatured;
